    /// <summary>
    /// Tab nhân thân — lưới + popup chi tiết (giống frmPersonalRelationDetail WinForm).
    /// </summary>
    public partial class TabNhanThan : ControlBase
    {
        private const string StoreSearch = "HRS_PersonalRelation_Search";
        private const string StoreRelationType = "GEN_RelationType_GETALL";

        private readonly HRS_Employee employeeDao = new HRS_Employee();

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                LoadRelationTypeDropdown();
                ApplyEditPermission();
            }
        }

        public void BindForEmployee(long employeeId, string employeeDisplay)
        {
            ViewState["EmpV2_NhanThan_EmployeeID"] = employeeId;
            ViewState["EmpV2_NhanThan_EmployeeDisplay"] = employeeDisplay ?? string.Empty;

            if (ddlRelationType.Items.Count <= 1)
                LoadRelationTypeDropdown();

            LoadGrid();
            ApplyEditPermission();
        }

        protected void btnAdd_Click(object sender, EventArgs e)
        {
            if (!CanEdit())
            {
                MsgBox.ShowWarning("Bạn không được phép thêm nhân thân hoặc đã hết hạn chỉnh sửa.");
                return;
            }

            ClearModalFields(true);
            RegisterShowModalScript();
            upNhanThan.Update();
        }

        protected void btnRefresh_Click(object sender, EventArgs e)
        {
            LoadGrid();
            upNhanThan.Update();
        }

        protected void gvNhanThan_RowCommand(object sender, GridViewCommandEventArgs e)
        {
            int index;
            if (!int.TryParse(Convert.ToString(e.CommandArgument), out index))
                return;

            if (index < 0 || index >= gvNhanThan.Rows.Count)
                return;

            if (e.CommandName == "EditRow")
            {
                if (!CanEdit())
                {
                    MsgBox.ShowWarning("Bạn không được phép sửa hoặc đã hết hạn chỉnh sửa.");
                    return;
                }

                LoadRowToModal(index);
                RegisterShowModalScript();
                upNhanThan.Update();
            }
            else if (e.CommandName == "DeleteRow")
            {
                if (!CanEdit())
                {
                    MsgBox.ShowWarning("Bạn không được phép xóa hoặc đã hết hạn chỉnh sửa.");
                    return;
                }

                DeleteRow(index);
                LoadGrid();
                upNhanThan.Update();
            }
        }

        protected void btnSaveModal_Click(object sender, EventArgs e)
        {
            if (!CanEdit())
            {
                MsgBox.ShowWarning("Bạn không được phép lưu hoặc đã hết hạn chỉnh sửa.");
                return;
            }

            if (!IsValidModal())
                return;

            long employeeId = GetEmployeeId();
            if (employeeId <= 0)
            {
                MsgBox.ShowWarning("Không xác định được nhân viên.");
                return;
            }

            SessionUser objUser = Session[Globals.USER] as SessionUser;
            if (objUser == null)
            {
                MsgBox.ShowWarning("Phiên làm việc đã hết. Vui lòng đăng nhập lại.");
                return;
            }

            string userName = objUser.UserName.ToLower();
            bool isNew = string.IsNullOrWhiteSpace(hdnPersonalRelationID.Value);

            HRS_PersonalRelation item = new HRS_PersonalRelation();
            if (!isNew)
            {
                long id;
                if (long.TryParse(hdnPersonalRelationID.Value, out id) && id > 0)
                    item.PersonalRelationID = id;
                else
                    isNew = true;
            }

            item.BeginTransaction();
            try
            {
                item.EmployeeID = employeeId;
                item.RelationTypeID = ParseInt(ddlRelationType.SelectedValue);
                item.FullName = txtFullName.Text.Trim();
                item.BirthDateText = txtBirthDateText.Text.Trim();
                item.Job = txtJob.Text.Trim();
                item.Tel = txtTel.Text.Trim();
                item.Address = txtAddress.Text.Trim();
                item.PersonID = txtPersonID.Text.Trim();
                item.Description = txtDescription.Text.Trim();

                bool result;
                if (isNew)
                {
                    item.CreatedUser = userName;
                    result = item.Add();
                }
                else
                {
                    item.UpdatedUser = userName;
                    result = item.Update();
                }

                if (!result)
                {
                    MsgBox.ShowWarning(isNew ? "Không thể thêm nhân thân." : "Không thể cập nhật nhân thân.");
                    return;
                }

                item.CommitTransaction();
                LoadGrid();
                ClearModalFields(false);
                upNhanThan.Update();
                RegisterHideModalScript();
                MsgBox.ShowInfo("Đã lưu thông tin nhân thân.");
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabNhanThan.Save: " + ex.Message);
                MsgBox.ShowError("Lỗi khi lưu thông tin nhân thân.");
            }
        }

        private void LoadGrid()
        {
            long employeeId = GetEmployeeId();
            DataTable dt = null;
            if (employeeId > 0)
            {
                try
                {
                    dt = employeeDao.GetDataTable(StoreSearch, "@EmployeeID", employeeId);
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine("TabNhanThan.LoadGrid: " + ex.Message);
                }
            }

            if (dt == null)
                dt = new DataTable();

            gvNhanThan.DataSource = dt;
            gvNhanThan.DataBind();
        }

        private void LoadRelationTypeDropdown()
        {
            try
            {
                DataTable dt = employeeDao.GetDataTable(StoreRelationType);
                EmployeeV2WebLookup.BindTable(ddlRelationType, dt, "RelationTypeID", "RelationTypeName");
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabNhanThan.LoadRelationTypeDropdown: " + ex.Message);
                EmployeeV2WebLookup.BindTable(ddlRelationType, null, "RelationTypeID", "RelationTypeName");
            }
        }

        private void LoadRowToModal(int rowIndex)
        {
            GridViewRow row = gvNhanThan.Rows[rowIndex];
            if (row == null)
                return;

            long personalRelationId = 0;
            if (gvNhanThan.DataKeys != null && rowIndex < gvNhanThan.DataKeys.Count)
            {
                object key = gvNhanThan.DataKeys[rowIndex].Value;
                if (key != null && key != DBNull.Value)
                    long.TryParse(key.ToString(), out personalRelationId);
            }

            hdnPersonalRelationID.Value = personalRelationId > 0 ? personalRelationId.ToString() : string.Empty;
            txtEmployeeDisplay.Text = GetEmployeeDisplay();

            SetTextFromCell(row, "FullName", txtFullName);
            SetTextFromCell(row, "PersonID", txtPersonID);
            SetTextFromCell(row, "BirthDateText", txtBirthDateText);
            SetTextFromCell(row, "Job", txtJob);
            SetTextFromCell(row, "Tel", txtTel);
            SetTextFromCell(row, "Address", txtAddress);
            SetTextFromCell(row, "Description", txtDescription);

            string relationTypeName = GetCellText(row, "RelationTypeName");
            if (!string.IsNullOrEmpty(relationTypeName))
            {
                ListItem li = ddlRelationType.Items.FindByText(relationTypeName);
                if (li != null)
                    ddlRelationType.SelectedValue = li.Value;
            }

            if (personalRelationId > 0)
            {
                HRS_PersonalRelation item = new HRS_PersonalRelation();
                item.PersonalRelationID = personalRelationId;
                if (item.Get())
                {
                    if (item.RelationTypeID != null)
                    {
                        string val = item.RelationTypeID.Value.ToString();
                        if (ddlRelationType.Items.FindByValue(val) != null)
                            ddlRelationType.SelectedValue = val;
                    }
                    txtFullName.Text = SafeText(item.FullName);
                    txtBirthDateText.Text = SafeText(item.BirthDateText);
                    txtJob.Text = SafeText(item.Job);
                    txtTel.Text = SafeText(item.Tel);
                    txtAddress.Text = SafeText(item.Address);
                    txtPersonID.Text = SafeText(item.PersonID);
                    txtDescription.Text = SafeText(item.Description);
                }
            }
        }

        private void DeleteRow(int rowIndex)
        {
            long personalRelationId = 0;
            if (gvNhanThan.DataKeys != null && rowIndex < gvNhanThan.DataKeys.Count)
            {
                object key = gvNhanThan.DataKeys[rowIndex].Value;
                if (key != null && key != DBNull.Value)
                    long.TryParse(key.ToString(), out personalRelationId);
            }

            if (personalRelationId <= 0)
                return;

            SessionUser objUser = Session[Globals.USER] as SessionUser;
            string userName = objUser != null ? objUser.UserName.ToLower() : string.Empty;

            HRS_PersonalRelation item = new HRS_PersonalRelation();
            item.PersonalRelationID = personalRelationId;
            item.DeletedUser = userName;
            item.BeginTransaction();
            try
            {
                if (!item.Delete())
                {
                    MsgBox.ShowWarning("Không thể xóa nhân thân.");
                    return;
                }
                item.CommitTransaction();
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabNhanThan.Delete: " + ex.Message);
                MsgBox.ShowError("Lỗi khi xóa nhân thân.");
            }
        }

        private bool IsValidModal()
        {
            if (string.IsNullOrWhiteSpace(txtFullName.Text))
            {
                MsgBox.ShowWarning("Bạn phải nhập họ tên người thân!");
                return false;
            }

            int relationTypeId = ParseInt(ddlRelationType.SelectedValue);
            if (relationTypeId <= 0)
            {
                MsgBox.ShowWarning("Bạn phải chọn quan hệ!");
                return false;
            }

            return true;
        }

        private void ClearModalFields(bool forAdd)
        {
            if (forAdd)
                hdnPersonalRelationID.Value = string.Empty;

            txtEmployeeDisplay.Text = GetEmployeeDisplay();
            txtFullName.Text = string.Empty;
            txtPersonID.Text = string.Empty;
            txtBirthDateText.Text = string.Empty;
            txtTel.Text = string.Empty;
            txtJob.Text = string.Empty;
            txtAddress.Text = string.Empty;
            txtDescription.Text = string.Empty;
            if (ddlRelationType.Items.Count > 0)
                ddlRelationType.SelectedIndex = 0;
        }

        private void ApplyEditPermission()
        {
            bool canEdit = CanEdit();
            if (btnAdd != null)
                btnAdd.Visible = canEdit;
            if (btnSaveModal != null)
                btnSaveModal.Visible = canEdit;
        }

        private bool CanEdit()
        {
            SessionUser objUser = Session[Globals.USER] as SessionUser;
            if (objUser == null)
                return false;

            SIM_Teacher sim = new SIM_Teacher();
            DataTable dtbTeacherInfo = sim.GetDataTable("SIM_Teacher_Employee", "@TeacherID", objUser.UserName.ToLower());
            if (dtbTeacherInfo == null || dtbTeacherInfo.Rows.Count == 0)
                return true;

            DateTime allowEditToDate;
            if (DateTime.TryParse(dtbTeacherInfo.Rows[0]["AllowEditToDate"].ToString(), out allowEditToDate))
                return DateTime.Now <= allowEditToDate;

            return true;
        }

        private long GetEmployeeId()
        {
            object o = ViewState["EmpV2_NhanThan_EmployeeID"];
            if (o == null)
                return 0;
            long id;
            long.TryParse(o.ToString(), out id);
            return id;
        }

        private string GetEmployeeDisplay()
        {
            object o = ViewState["EmpV2_NhanThan_EmployeeDisplay"];
            if (o == null)
                return string.Empty;
            return o.ToString();
        }

        private void RegisterShowModalScript()
        {
            ScriptManager.RegisterStartupScript(upNhanThan, upNhanThan.GetType(), "EmpV2ShowNhanThanModal", "empv2OpenNhanThanModal();", true);
        }

        private void RegisterHideModalScript()
        {
            ScriptManager.RegisterStartupScript(upNhanThan, upNhanThan.GetType(), "EmpV2HideNhanThanModal", "empv2HideNhanThanModal();", true);
        }

        private static int ParseInt(string input)
        {
            if (string.IsNullOrWhiteSpace(input))
                return 0;
            int val;
